apitable_create_record.beforeRequest:
const given = typeof inputs.fields === 'string' ? JSON.parse(inputs.fields || '{}') : (inputs.fields || {});
const values = {};
for (const [name, value] of Object.entries(given)) if (value !== undefined && value !== '') values[name] = value;
const skipped = ['Attachment', 'AutoNumber', 'Cascader', 'CreatedBy', 'CreatedTime', 'Formula', 'LastModifiedTime', 'LastModifiedBy', 'MagicLookUp', 'OneWayLink'];
const fields = {};
for (const field of call({method: 'GET', url: '/v1/datasheets/' + encodeURIComponent(inputs.datasheet_id) + '/fields'}).data.fields) {
  const name = field.name;
  if (skipped.includes(field.type) || !(name in values)) continue;
  const value = values[name];
  if (['Number', 'Rating', 'Currency', 'Percent'].includes(field.type)) fields[name] = Number(value);
  else if (field.type === 'Member') {
    const ids = Array.isArray(value) ? value.map(String) : [String(value)];
    if (ids.length === 0) continue;
    const members = field.property && field.property.options ? field.property.options.filter((option) => ids.includes(option.id)) : undefined;
    if (members !== undefined) fields[name] = members;
  } else if (['MultiSelect', 'TwoWayLink'].includes(field.type)) {
    if (!Array.isArray(value) || value.length === 0) continue;
    fields[name] = value;
  } else fields[name] = value;
}
request.body = {records: [{fields}]};
return request;

